  'card.title': 'Crypto Card',
  'card.heroTagline': 'полностью бесплатная карта для трат с крипто-баланса.',
  'card.lead': 'Карта работает в России точно так же, как и в любой другой стране — без региональных ограничений и урезанных условий.',
  'card.whyKycTitle': 'Почему для карты нужна верификация',
  'card.whyKycText': 'Торговать на бирже можно без верификации (KYC). Но саму карту выпускает партнёрский банк вместе с платёжной системой (Visa/Mastercard) — они по закону требуют полную верификацию владельца карты для любого эмитента, независимо от страны регистрации компании. Поэтому верификация обязательна только для карты и операций с фиатом, а не для обычной криптоторговли.',
  'card.joinedPrefix': 'Заявка на карту отправлена',
  'card.joinedSince': 'с {date} — мы свяжемся с тобой по email с дальнейшими шагами.',
  'card.joinBtn': 'Оформить карту',
  'card.needVerification': 'Чтобы оформить карту, сначала пройди верификацию.',
  'card.goVerify': 'Пройти верификацию →',
  'card.joinError': 'Не удалось отправить заявку на карту',
  'card.faqTitle': 'Частые вопросы',
  'card.faq.order.q': 'Как оформить карту?',
  'card.faq.order.a': 'Нажми «Оформить карту». Потребуется пройти верификацию личности (KYC) — это обязательное требование платёжной системы для любого держателя карты, а не наша прихоть. После отправки заявки мы свяжемся с тобой по email.',
  'card.faq.delivery.q': 'Какие сроки выпуска?',
  'card.faq.delivery.a': 'После одобрения заявки мы сообщим статус выпуска карты и дальнейшие шаги по email — сроки зависят от способа доставки и страны.',
  'card.faq.limits.q': 'Какие лимиты по карте?',
  'card.faq.limits.a': 'Лимиты на траты и снятие наличных зависят от уровня верификации и VIP-статуса аккаунта. Точные значения будут указаны при оформлении.',
  'card.faq.currencies.q': 'Какие валюты поддерживаются?',
  'card.faq.currencies.a': 'Списание происходит напрямую с твоего крипто-баланса (BTC, ETH, USDT и другие поддерживаемые активы) по рыночному курсу, без комиссии за конвертацию.',
  'card.feature1.title': 'Apple Pay и Google Pay',
  'card.feature1.text': 'Привяжи карту и плати в супермаркетах, на заправках и в интернете — везде, где принимают Apple Pay/Google Pay.',
  'card.feature2.title': 'Без комиссий за обслуживание',
  'card.feature2.text': 'Бесплатное открытие и ведение карты — никакой ежемесячной или ежегодной платы.',
  'card.feature3.title': 'Без комиссии за конвертацию',
  'card.feature3.text': 'Оплата списывается напрямую с крипто-баланса по рыночному курсу, без скрытой наценки на конвертацию.',
  'card.feature4.title': 'Снятие наличных без комиссий',
  'card.feature4.text': 'Снятие в банкоматах без дополнительной комиссии от нас (лимиты банкомата и партнёра могут применяться).',
  'card.feature5.title': '8% кешбэка',
  'card.feature5.text': 'Для VIP-клиентов — начисляется автоматически на внутренний баланс. Условия VIP-статуса ниже.',
  'card.vipTitle': 'VIP-кешбэк 8%',
  'card.vipLead': 'Карта полностью бесплатна: без платы за выпуск, за обслуживание и за конвертацию. Для VIP-клиентов дополнительно действует кешбэк 8% — на покупки картой и на депозиты.',
