  'marketing.faqLabel': 'Вопросы и ответы',
  'marketing.faqTitle': 'Частые вопросы',
  'marketing.faq.q1': 'Что такое VOLTEX?',
  'marketing.faq.a1':
    'VOLTEX — криптовалютная биржа со спотовой торговлей, фьючерсами и копитрейдингом в едином терминале, без обязательной верификации личности для торговли.',
  'marketing.faq.q2': 'Нужна ли верификация (KYC) для торговли?',
  'marketing.faq.a2':
    'Нет. Депозиты, выводы и торговля на споте и фьючерсах не требуют KYC. Верификация нужна только для отдельных продуктов, например крипто-карты.',
  'marketing.faq.q3': 'Как защищён мой аккаунт?',
  'marketing.faq.a3':
    'Двухфакторная аутентификация, журнал входов и лимиты на вывод помогают защитить аккаунт. Ключи и средства остаются на твоём балансе биржи.',
  'marketing.faq.q4': 'Какие комиссии на сделки?',
  'marketing.faq.a4':
    'Спотовая торговля — 0% комиссии. По фьючерсам действует комиссия мейкера/тейкера, которая видна в форме ордера перед подтверждением сделки.',
  'marketing.faq.q5': 'Можно ли копировать других трейдеров?',
  'marketing.faq.a5': 'Копитрейдинг доступен клиентам с депозитом от $20 000. Свяжись с поддержкой, чтобы получить доступ.',
  'marketing.faq.q6': 'Есть ли мобильное приложение?',
  'marketing.faq.a6':
    'Отдельного приложения пока нет — интерфейс полностью адаптирован под мобильный браузер и открывает весь функционал терминала.',

  'marketing.finalCtaTitle': 'Начни торговать за пару минут',
