  'card.lead': 'The card works in Russia exactly the same as in any other country — no regional restrictions, no reduced terms.',
  'card.whyKycTitle': 'Why the card requires verification',
  'card.whyKycText': "You can trade on the exchange without verification (KYC). But the card itself is issued by a partner bank together with a payment network (Visa/Mastercard) — they legally require full cardholder verification for any issuer, regardless of the company's country of registration. That's why verification is required only for the card and fiat operations, not for regular crypto trading.",
