  'marketing.faq.q1': 'What is VOLTEX?',
  'marketing.faq.a1': 'VOLTEX is a crypto exchange with spot, futures and copy trading in a single terminal, with no identity verification required to trade.',
  'marketing.faq.q2': 'Do I need to verify (KYC) to trade?',
  'marketing.faq.a2': 'No. Deposits, withdrawals and spot/futures trading require no KYC. Verification is only needed for specific products, like the crypto card.',
  'marketing.faq.q3': 'How is my account protected?',
  'marketing.faq.a3': 'Two-factor authentication, a login history and withdrawal limits help protect your account. Your funds stay on your own exchange balance.',
  'marketing.faq.q4': 'What are the trading fees?',
  'marketing.faq.a4': 'Spot trading is 0% commission. Futures carry a maker/taker fee, shown in the order form before you confirm the trade.',
