  'card.title': 'Tarjeta cripto',
  'card.heroTagline': 'una tarjeta completamente gratuita para gastar directamente desde tu saldo cripto.',
  'card.lead': 'La tarjeta funciona en Rusia exactamente igual que en cualquier otro país — sin restricciones regionales ni condiciones reducidas.',
  'card.whyKycTitle': 'Por qué la tarjeta requiere verificación',
  'card.whyKycText': 'Puedes operar en el exchange sin verificación (KYC). Pero la tarjeta en sí la emite un banco asociado junto con una red de pago (Visa/Mastercard) — legalmente exigen la verificación completa del titular para cualquier emisor, sin importar el país de registro de la empresa. Por eso la verificación solo se requiere para la tarjeta y las operaciones en moneda fiduciaria, no para el trading normal de criptomonedas.',
  'card.joinedPrefix': 'Tu solicitud de tarjeta fue enviada',
  'card.joinedSince': 'desde {date} — te enviaremos un correo con los próximos pasos.',
  'card.joinBtn': 'Obtener tarjeta',
  'card.needVerification': 'Para obtener una tarjeta, primero completa la verificación.',
  'card.goVerify': 'Completar verificación →',
  'card.joinError': 'No se pudo enviar la solicitud de tarjeta',
  'card.faqTitle': 'Preguntas frecuentes',
  'card.faq.order.q': '¿Cómo obtengo una tarjeta?',
  'card.faq.order.a': 'Toca "Obtener tarjeta". Deberás completar la verificación de identidad (KYC) — un requisito legal de la red de pago para cualquier titular, no algo que elegimos nosotros. Te enviaremos un correo una vez que se envíe tu solicitud.',
  'card.faq.delivery.q': '¿Cuál es el plazo de emisión?',
  'card.faq.delivery.a': 'Una vez aprobada tu solicitud, te enviaremos por correo el estado de emisión de la tarjeta y los próximos pasos — el tiempo depende del método de entrega y tu país.',
  'card.faq.limits.q': '¿Cuáles son los límites de la tarjeta?',
  'card.faq.limits.a': 'Los límites de gasto y retiro de efectivo dependen del nivel de verificación de tu cuenta y tu estado VIP. Las cifras exactas se muestran al completar la solicitud.',
  'card.faq.currencies.q': '¿Qué monedas son compatibles?',
  'card.faq.currencies.a': 'Los cargos se toman directamente de tu saldo cripto (BTC, ETH, USDT y otros activos admitidos) al tipo de cambio de mercado, sin comisión de conversión.',
  'card.feature1.title': 'Apple Pay y Google Pay',
  'card.feature1.text': 'Agrega la tarjeta y paga en supermercados, gasolineras y en línea — donde se acepte Apple Pay/Google Pay.',
  'card.feature2.title': 'Sin cargos de mantenimiento',
  'card.feature2.text': 'Gratis para abrir y mantener — sin cuota mensual ni anual.',
  'card.feature3.title': 'Sin comisión de conversión',
  'card.feature3.text': 'Los pagos se cargan directamente desde tu saldo cripto al tipo de cambio de mercado, sin recargo de conversión oculto.',
  'card.feature4.title': 'Retiros de efectivo sin comisión',
  'card.feature4.text': 'Retiros en cajeros automáticos sin cargo adicional de nuestra parte (pueden aplicar límites del cajero y del socio).',
  'card.feature5.title': '8% de cashback',
  'card.feature5.text': 'Para clientes VIP — se acredita automáticamente a tu saldo interno. Condiciones VIP abajo.',
  'card.vipTitle': '8% de cashback VIP',
  'card.vipLead': 'La tarjeta es completamente gratuita: sin comisión de emisión, sin cuota de mantenimiento, sin comisión de conversión. Los clientes VIP además reciben 8% de cashback — en compras con tarjeta y en depósitos.',
