  'marketing.faqTitle': 'Preguntas frecuentes',
  'marketing.faq.q1': '¿Qué es VOLTEX?',
  'marketing.faq.a1': 'VOLTEX es un exchange de criptomonedas con trading spot, futuros y copy trading en una sola terminal, sin necesidad de verificación de identidad para operar.',
  'marketing.faq.q2': '¿Necesito verificarme (KYC) para operar?',
  'marketing.faq.a2': 'No. Los depósitos, retiros y el trading spot/futuros no requieren KYC. La verificación solo es necesaria para productos específicos, como la tarjeta cripto.',
  'marketing.faq.q3': '¿Cómo está protegida mi cuenta?',
  'marketing.faq.a3': 'La autenticación de dos factores, el historial de inicios de sesión y los límites de retiro ayudan a proteger tu cuenta. Tus fondos permanecen en tu propio saldo del exchange.',
  'marketing.faq.q4': '¿Cuáles son las comisiones de trading?',
  'marketing.faq.a4': 'El trading spot tiene 0% de comisión. Los futuros tienen una comisión maker/taker, que se muestra en el formulario de orden antes de confirmar la operación.',
  'marketing.faq.q5': '¿Puedo copiar a otros traders?',
  'marketing.faq.a5': 'El copy trading está disponible para clientes con un depósito de $20,000+. Contacta a soporte para obtener acceso.',
  'marketing.faq.q6': '¿Hay una app móvil?',
  'marketing.faq.a6': 'Aún no hay una app dedicada — la interfaz es totalmente responsiva en navegadores móviles y expone toda la terminal.',
  'marketing.finalCtaTitle': 'Comienza a operar en minutos',
  'marketing.finalCtaSubtitle': 'Regístrate y obtén acceso a la terminal completa de VOLTEX — sin verificación necesaria para empezar a operar.',
